v=0; if git diff HEAD --unified=0 -- '*.swift' ':(exclude)Tests/**' | grep -E '^\+' | grep -vE '^\+\+\+' | sed 's#//.*##' | grep -qE '(^|[^A-Za-z0-9_])try\?'; then v=1; fi; while IFS= read -r f; do if sed 's#//.*##' "$f" | grep -qE '(^|[^A-Za-z0-9_])try\?'; then v=1; fi; done < <(git ls-files --others --exclude-standard -- '*.swift' | grep -v '^Tests/'); if [ $v = 1 ]; then echo VIOLATED; else echo OBEYED; fi
